package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarUtils_parseOctal_TriageGen2Test {











    @Test
    public void testParseOctal_AllSpacesAndNuls() {
        // If the buffer starts with 0, it returns 0 early. 
        // If it starts with space, it skips spaces. 
        // If it contains only spaces/nulls after skipping, end becomes <= start.
        byte[] buffer = "  \0  ".getBytes();
        // To trigger the 'buffer[start] == 0' branch, we need a 0 at the offset
        byte[] bufferZero = {0, 0, 0};
        assertEquals(0L, TarUtils.parseOctal(bufferZero, 0, 3));
    }














}

