package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarUtils_parseOctal_TriageGen2Test {

























    @Test
    public void testParseOctal_EmptyAfterTrimming() {
        // If buffer is all spaces/nulls but doesn't start with 0
        byte[] buffer = {' ', ' ', 0, 0};
        // start will skip spaces, start=2. 
        // end-1 is buffer[3]=0. end decreases until end=2.
        // loop start < end won't execute. result = 0.
        long result = TarUtils.parseOctal(buffer, 0, 4);
        assertEquals(0L, result);
    }
}
